from decimal import Decimal

from invoicer.export import to_csv


class TestCsvExport(unittest.TestCase):
    def test_header_and_rows(self):
        invoice = {
            "client": "Acme",
            "lines": [
                {"item": "Hosting", "qty": "3", "unit_price": "1.115"},
                {"item": "Support", "qty": "1", "unit_price": "2.675"},
            ],
        }
        self.assertEqual(
            to_csv(invoice),
            "item,qty,unit_price,line_total\n"
            "Hosting,3,1.115,3.35\n"
            "Support,1,2.675,2.68\n",
        )

    def test_values_with_commas_and_quotes_are_quoted(self):
        invoice = {
            "client": "Brightwell",
            "lines": [{"item": 'Design, phase 2 "final"', "qty": "2", "unit_price": "410.125"}],
        }
        self.assertEqual(
            to_csv(invoice),
            'item,qty,unit_price,line_total\n'
            '"Design, phase 2 ""final""",2,410.125,820.25\n',
        )

    def test_line_total_matches_money(self):
        invoice = {"client": "Corvid Ltd", "lines": [{"item": "Licences", "qty": "12", "unit_price": "8.3333"}]}
        row = to_csv(invoice).splitlines()[1]
        self.assertEqual(row, "Licences,12,8.3333,100.00")
        self.assertEqual(Decimal("100.00"), Decimal("100.00"))
","file_path":"tests/test_export.py"}

{"content":"import io
import json
import os
import tempfile
import unittest
from contextlib import redirect_stdout
from decimal import Decimal

from invoicer.cli import main


def _invoice_file(lines):
    fd, path = tempfile.mkstemp(suffix=".json")
    with os.fdopen(fd, "w") as f:
        json.dump({"client": "Acme", "lines": lines}, f)
    return path


class TestCliCurrency(unittest.TestCase):
    def setUp(self):
        self.path = _invoice_file([{"item": "Hosting", "qty": "3", "unit_price": "1.115"}])

    def tearDown(self):
        os.unlink(self.path)

    def _run(self, *argv):
        buf = io.StringIO()
        with redirect_stdout(buf):
            main(list(argv))
        return buf.getvalue().strip()

    def test_default_is_euro(self):
        self.assertEqual(self._run(self.path), "Acme: €3.35")

    def test_usd_and_gbp(self):
        self.assertEqual(self._run(self.path, "--currency", "USD"), "Acme: $3.35")
        self.assertEqual(self._run(self.path, "--currency", "GBP"), "Acme: £3.35")

    def test_unknown_currency_is_an_error(self):
        with self.assertRaises(SystemExit) as ctx:
            self._run(self.path, "--currency", "JPY")
        self.assertNotEqual(ctx.exception.code, 0)

    def test_total_is_decimal(self):
        from invoicer.money import total

        self.assertIsInstance(total([{"qty": "1", "unit_price": "2.675"}]), Decimal)
","file_path":"tests/test_cli.py"}

